using Minio;
using Minio.DataModel.Tags;

var minio = new MinioClient()
    .WithEndpoint("localhost:9000")
    .WithCredentials("minioadmin", "minioadmin")
    .WithSSL(false)
    .Build();

string bucketName = "test-bucket";
string objectName = "test.txt";
string filePath = "./test.txt";

// Create bucket if it does not exist
bool found = await minio.BucketExistsAsync("test-bucket");
if (!found)
{
    await minio.MakeBucketAsync("test-bucket");
}

// Upload file
await minio.UploadFileAsync("test-bucket", objectName, filePath);
Console.WriteLine("Uploaded to Minio.");

// List objects
await foreach (var item in minio.ListObjectsAsync("test-bucket"))
{
    Console.WriteLine(item.Key);
}
